counterexample:
INSERT INTO Drinker (name, address) VALUES ('Alice', '123 Main St');
INSERT INTO Bar (name, address) VALUES ('Bar A', '456 Elm St');
INSERT INTO Beer (name, brewer) VALUES ('Beer X', 'Brewer A'), ('Beer Y', 'Brewer B');
INSERT INTO Serves (bar, beer, price) VALUES ('Bar A', 'Beer X', 10.00), ('Bar A', 'Beer Y', 15.00);
INSERT INTO Likes (drinker, beer) VALUES ('Alice', 'Beer X');

