q2:
WITH ValidBeers AS (SELECT beer FROM serves WHERE serves.bar IN (SELECT bar FROM frequents WHERE drinker LIKE 'B%') GROUP BY beer HAVING COUNT(bar) >= 2),
BeerPrices AS (SELECT serves.beer, serves.price FROM serves FULL OUTER JOIN ValidBeers ON serves.beer = ValidBeers.beer)
SELECT bp.beer, MAX(bp.price) - MIN(bp.price) AS price_gap, AVG(bp.price) AS avg_price FROM BeerPrices bp GROUP BY bp.beer ORDER BY bp.beer;

